export class PEDSDictionaryUtils {
  static findByCode(code: string): MedicalCodeEntry | undefined {
    return PEDS_ICD10_DATABASE.find(item => item.code.toLowerCase() === code.toLowerCase());
  }

  static searchByDescription(query: string): MedicalCodeEntry[] {
    const q = query.toLowerCase();
    return PEDS_ICD10_DATABASE.filter(item => item.description.toLowerCase().includes(q));
  }
}
